UPDATE t_i18n_locale
SET native_name = #{next.nativeName}, english_name = #{next.englishName},
    text_direction = #{next.textDirection}, status = #{next.status}, sort_order = #{next.sortOrder},
    version = version + 1, updated_by = #{next.updatedBy}, update_time = #{next.updateTime}
WHERE locale_id = #{row.localeId} AND version = #{row.version}
